string phase = "created";
string requestId = "Q31";
var elapsed = System.Diagnostics.Stopwatch.StartNew();
try {
    phase = "connect";
    await ConnectLabAsync();
    phase = "write";
    await WriteLabAsync();
    phase = "read-complete-message";
    byte[] reply = await ReadLabMessageAsync();
    phase = "parse-and-match";
    ParseLabReply(requestId, reply);
    phase = "application-success";
} catch (Exception e) {
    Console.WriteLine($"request={requestId} phase={phase} elapsedMs={elapsed.Elapsed.TotalMilliseconds:F1} error={e.GetType().Name}");
    throw; // preserve stack; outer policy decides recovery
}
